random = []
seen = {}
while random.size < 2500
  n = 1 + rand(6)
  s = (1..n).map { tokens.sample }.join(["", " ", "", "-", "/", "."].sample)
  next if seen[s]
  seen[s] = true
  random << s
end

puts({ "today" => Date.today.iso8601 }.to_json)
(fixed + random).each do |s|
  out = begin
    d = Date.parse(s)
    format("%d-%02d-%02d", d.year, d.mon, d.mday)
  rescue ArgumentError, RangeError
    nil
  end
  puts({ "in" => s, "out" => out }.to_json)
end
